			xpad->delayed_init_done = true;
			error = xpad_start_input(xpad);
			if (error)
				dev_warn(&xpad->dev->dev,
					 "unable to start delayed input: %d\n",
					 error);
		}
	} else if (data[0] == GIP_CMD_INPUT) { /* The main valid packet type for inputs */
		/* menu/view buttons */

